/// The icon the local MCP endpoint advertises to clients.
///
/// A 512×512 PNG (palette, ~3.4 KB) rasterised from the app's launcher mark
/// `mobile/android/app/src/main/res/drawable/ic_launcher_foreground.xml` on the
/// white adaptive background. It is embedded here rather than shipped as a
/// Flutter asset so the transport can answer `GET /icon.png` from any isolate
/// without going through the asset bundle.
library;

import 'dart:convert';
import 'dart:typed_data';

/// `image/png` bytes of the icon, base64 so the analyzer keeps it readable.
const String _iconPngBase64 =
    '';

/// Square edge length of the embedded PNG, used for the `sizes` of the icon
/// entry in `initialize`.
const int mcpIconEdge = 512;

/// MIME type of [mcpIconPngBytes].
const String mcpIconMimeType = 'image/png';

Uint8List? _cached;

/// The PNG bytes served at `/icon.png` and advertised in `serverInfo.icons`.
Uint8List get mcpIconPngBytes => _cached ??= base64Decode(_iconPngBase64);
